import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import {useTranslation} from 'react-i18next'
import {LEAGUE_ORDER, LEAGUE_META} from './constants'

const LEAGUES = LEAGUE_ORDER.map(key => ({ key, ...LEAGUE_META[key] }))

function FlipDigit({ ch }) {
    const prevRef = useRef(ch)
    const [prev, setPrev] = useState(ch)
    const [animKey, setAnimKey] = useState(0)
    const [animating, setAnimating] = useState(false)

    useLayoutEffect(() => {
        if (ch !== prevRef.current) {
            setPrev(prevRef.current)
            prevRef.current = ch
            setAnimKey(k => k + 1)
            setAnimating(true)
        }
    }, [ch])

    useEffect(() => {
        if (!animating) return
        const t = setTimeout(() => setAnimating(false), 300)
        return () => clearTimeout(t)
    }, [animating])

    return (
        <span className={`d-inline-block flip-digit overflow-hidden position-relative shadow${animating ? ' flip-digit-animate' : ''}`}>
            <span className="end-0 fd-piece fd-top h-50 overflow-hidden position-absolute start-0 top-0"><span className="digit">{ch}</span></span>
            <span className="bottom-0 end-0 fd-piece fd-bottom h-50 overflow-hidden position-absolute start-0"><span className="digit">{ch}</span></span>
            {animKey > 0 && <span key={animKey} className="end-0 fd-flap fd-piece overflow-hidden position-absolute start-0 top-0"><span className="digit">{prev}</span></span>}
        </span>
    )
}

export default function LeagueFilters({ leagueCounts, isAnimating, anim, activeLeagueGoals, randomGoal, jsonData, searchGoal }) {
    const {t} = useTranslation()
    return (
        <div className="d-flex flex-wrap align-items-stretch column-gap-2 row-gap-3 mb-3" id="league-filters">
            {LEAGUES.map(({ key, title }) => (
                <button key={key} className="button counter" data-ga={title} disabled={isAnimating} onClick={() => randomGoal(jsonData.filter(item => item.league === key))} title={t(`leagueLabel.${key}`)} type="button">
                    <div className="h4 m-0" data-goals={leagueCounts[key]}>{anim(leagueCounts[key])}</div>
                    <div>{t(`leagueLabel.${key}`)}</div>
                </button>
            ))}
            <button className="button" data-ga="Total" disabled={isAnimating || activeLeagueGoals.length === 0} onClick={() => randomGoal(activeLeagueGoals)} title="Total" type="button">
                <span className="h2 m-0" data-goals={activeLeagueGoals.length}>{isAnimating ? anim(activeLeagueGoals.length) : activeLeagueGoals.length}</span>
            </button>
            {(() => {
                const raw = String(searchGoal)
                const formatted = raw.includes('.')
                    ? raw.split('.')[0] + '.' + raw.split('.')[1].padEnd(2, '0')
                    : raw
                const digitCount = formatted.replace('.', '').length
                const padCount = Math.max(0, 3 - digitCount)
                const items = []
                let rIdx = digitCount + padCount - 1
                for (let i = 0; i < padCount; i++) items.push(<FlipDigit key={`r${rIdx--}`} ch={!formatted ? 'OVI'[i] : ''} />)
                for (const ch of formatted) {
                    if (ch === '.') items.push(<span key="sep" className="d-inline-block fd-dot fd-piece flip-digit fw-bold h4 text-center shadow text-white"><strong className="digit">.</strong></span>)
                    else items.push(<FlipDigit key={`r${rIdx--}`} ch={ch} />)
                }
                return <div className="align-items-stretch d-flex gap-1 justify-content-start user-select-none" id="flip-counter" aria-label={formatted ? `Goal ${formatted}` : ''}>{items}</div>
            })()}
        </div>
    )
}
